"use client";

import React, { useRef } from "react";
import { Canvas, useFrame } from "@react-three/fiber";
import { Float } from "@react-three/drei";
import * as THREE from "three";

interface SilkSculptureProps {
  mode: "silk" | "velvet";
}

function PearlRibbon({ mode }: SilkSculptureProps) {
  const groupRef = useRef<THREE.Group>(null);
  const knotRef = useRef<THREE.Mesh>(null);

  useFrame((state, delta) => {
    const dt = Math.min(delta, 0.05);
    if (knotRef.current) {
      knotRef.current.rotation.y += dt * 0.22;
      knotRef.current.rotation.x += dt * 0.08;
    }
    if (groupRef.current) {
      const targetX = state.pointer.y * 0.18;
      const targetY = state.pointer.x * 0.24;
      groupRef.current.rotation.x = THREE.MathUtils.lerp(
        groupRef.current.rotation.x,
        targetX,
        0.04
      );
      groupRef.current.rotation.y = THREE.MathUtils.lerp(
        groupRef.current.rotation.y,
        targetY,
        0.04
      );
    }
  });

  const ribbonColor = mode === "silk" ? "#F3D3DA" : "#E8B4BE";
  const pearlColor = mode === "silk" ? "#FFF9F7" : "#F5E4E7";
  const accentColor = mode === "silk" ? "#D68295" : "#C97588";

  return (
    <group ref={groupRef}>
      <Float speed={1.4} rotationIntensity={0.22} floatIntensity={0.45}>
        {/* Sculptural silk ribbon */}
        <mesh ref={knotRef} scale={0.92}>
          <torusKnotGeometry args={[1.08, 0.28, 220, 48, 2, 3]} />
          <meshPhysicalMaterial
            color={ribbonColor}
            roughness={0.2}
            metalness={0.06}
            clearcoat={0.95}
            clearcoatRoughness={0.12}
            iridescence={0.65}
            iridescenceIOR={1.3}
            sheen={0.9}
            sheenColor={pearlColor}
          />
        </mesh>

        {/* Delicate floating pearl accents */}
        <mesh position={[1.65, 1.05, 0.35]}>
          <sphereGeometry args={[0.19, 32, 32]} />
          <meshPhysicalMaterial
            color={pearlColor}
            roughness={0.12}
            clearcoat={1}
            iridescence={0.5}
          />
        </mesh>
        <mesh position={[-1.55, -0.95, 0.5]}>
          <sphereGeometry args={[0.13, 32, 32]} />
          <meshPhysicalMaterial
            color={accentColor}
            roughness={0.18}
            clearcoat={0.95}
          />
        </mesh>
        <mesh position={[-1.25, 1.25, -0.4]}>
          <sphereGeometry args={[0.09, 28, 28]} />
          <meshPhysicalMaterial color={pearlColor} roughness={0.14} clearcoat={1} />
        </mesh>
      </Float>
    </group>
  );
}

export default function SilkSculpture({ mode }: SilkSculptureProps) {
  return (
    <div className="h-full w-full select-none">
      <Canvas
        camera={{ position: [0, 0, 5.4], fov: 40 }}
        dpr={[1, 2]}
        gl={{ antialias: true, alpha: true }}
      >
        <ambientLight intensity={mode === "silk" ? 1.2 : 0.9} />
        <directionalLight position={[4, 6, 5]} intensity={1.8} color="#FFF6F4" />
        <directionalLight position={[-5, -3, 3]} intensity={1.1} color="#F2C6D0" />
        <pointLight position={[0, 3, 2]} intensity={0.9} color="#FFE9E1" />
        <PearlRibbon mode={mode} />
      </Canvas>
    </div>
  );
}
